# codec plugin

/*
Codec Plugin 可以支持在 Codec 中自定义编码解码，自定义 Bypass 与字符串处理函数

函数定义非常简单

func(i: string) string
*/

handle = func(origin /*string*/) {  
   value=str.TrimSpace(origin)  
   t='时间戳解析失败!!!'  
   if str.IsDigit(value){  
    timestamp_val = int(value)  
    // 检测是否为毫秒级时间戳（通常大于10位数）  
    if timestamp_val > int("9999999999") {  
        // 毫秒级时间戳，转换为秒  
        t = timestampToDatetime(timestamp_val / 1000)  
    } else {  
        // 秒级时间戳  
        t = timestampToDatetime(timestamp_val)  
    }  
   }  
   n=time.now().Format("2006-01-02 15:04:05")  
   nt=timestamp()  
  
    s=f`时间戳: ${value}  
时间: ${t}  
  
当前时间: ${n}  
当前时间戳: ${nt}  
`  
    return s  
}
